// Extraer datos del payload del backend
const body = $input.first().json.body || $input.first().json;
const cargos = body.cargos || [];
const masters = body.masters || [];
const uploadId = body.upload_id;
const backendUrl = body.backend_url || 'https://shr-backend-prod.onrender.com';

// Construir lista de cargos maestros para el prompt
const mastersText = masters.slice(0, 40).map(m => 
  `- ${m.nombre}: ${(m.descripcion || '').substring(0, 120)}`
).join('\n');

// Procesar cada cargo
const items = cargos.map(cargo => ({
  json: {
    cargo_id: cargo.id,
    cargo_nombre: cargo.nombre,
    cargo_area: cargo.area || 'N/A',
    cargo_descripcion: cargo.descripcion_empresa || '',
    upload_id: uploadId,
    backend_url: backendUrl,
    masters_text: mastersText,
    prompt: `Eres experto en homologación de cargos de RRHH en Colombia.\n\nCARGO A HOMOLOGAR:\n- Nombre: ${cargo.nombre}\n- Área: ${cargo.area || 'N/A'}\n- Descripción: ${cargo.descripcion_empresa || 'No disponible'}\n\nCARGOS MAESTROS DISPONIBLES:\n${mastersText}\n\nResponde SOLO con JSON:\n{"cargo_homologado": "NOMBRE EXACTO DEL MAESTRO", "justificacion": "Razón breve (máx 80 palabras)", "status": "homologado"}\n\nSi no hay coincidencia:\n{"cargo_homologado": "SIN COINCIDENCIA", "justificacion": "No hay cargo maestro similar.", "status": "sin_coincidencia"}`
  }
}));

return items;

// Parsear respuesta de OpenRouter
const items = [];

for (const item of $input.all()) {
  try {
    const responseBody = item.json;
    const inputData = $('Preparar Cargos').item.json;

    let content = responseBody.choices?.[0]?.message?.content || '';

    if (content.includes('```json')) {
      content = content.split('```json')[1].split('```')[0].trim();
    } else if (content.includes('```')) {
      content = content.split('```')[1].split('```')[0].trim();
    }

    let result;
    try {
      result = JSON.parse(content);
    } catch(e) {
      result = {
        cargo_homologado: 'SIN COINCIDENCIA',
        justificacion: 'Error: ' + content.substring(0, 80),
        status: 'sin_coincidencia'
      };
    }

    items.push({
      json: {
        cargo_id: inputData.cargo_id,
        cargo_homologado: result.cargo_homologado || 'SIN COINCIDENCIA',
        justificacion: result.justificacion || '',
        status: result.status || 'sin_coincidencia',
        upload_id: inputData.upload_id,
        backend_url: inputData.backend_url
      }
    });
  } catch(e) {
    items.push({
      json: {
        cargo_id: $('Preparar Cargos').item.json.cargo_id,
        cargo_homologado: 'SIN COINCIDENCIA',
        justificacion: 'Error: ' + e.message,
        status: 'error',
        upload_id: $('Preparar Cargos').item.json.upload_id,
        backend_url: $('Preparar Cargos').item.json.backend_url
      }
    });
  }
}

return items;
